import Plugin from '@jbrowse/core/Plugin'
import { ConfigurationSchema } from '@jbrowse/core/configuration'
import { isAbstractMenuManager } from '@jbrowse/core/util'
import { types } from '@jbrowse/mobx-state-tree'
import GridOn from '@mui/icons-material/GridOn'

import AddHighlightModelF from './AddHighlightModel'
import BgzipFastaMsaAdapterF from './BgzipFastaMsaAdapter'
import LaunchMsaViewF from './LaunchMsaView'
import LaunchMsaViewExtensionPointF from './LaunchMsaViewExtensionPoint'
import MsaViewF from './MsaViewPanel'
import { launchMsaView } from './utils/launchMsaView'
import { version } from './version'

import type PluginManager from '@jbrowse/core/PluginManager'
import type { AbstractSessionModel } from '@jbrowse/core/util'

export default class MsaViewPlugin extends Plugin {
  name = 'MsaViewPlugin'
  version = version

  install(pluginManager: PluginManager) {
    MsaViewF(pluginManager)
    LaunchMsaViewF(pluginManager)
    LaunchMsaViewExtensionPointF(pluginManager)
    AddHighlightModelF(pluginManager)
    BgzipFastaMsaAdapterF(pluginManager)
  }

  configure(pluginManager: PluginManager) {
    // a throw here error-pages the whole app, and a menu entry is not worth a
    // session: every released host's File menu already throws on append
    try {
      if (isAbstractMenuManager(pluginManager.rootModel)) {
        pluginManager.rootModel.appendToSubMenu(['Add'], {
          label: 'Multiple sequence alignment view',
          icon: GridOn,
          onClick: (session: AbstractSessionModel) => {
            // stacked, by default: nothing was launched from, so there is no
            // connected view for it to sit beside
            launchMsaView(session, {}).catch((e: unknown) => {
              console.error(e)
              session.notifyError(`${e}`, e)
            })
          },
        })
      }
    } catch (e) {
      console.error(
        'jbrowse-plugin-msaview: could not add the Add menu item',
        e,
      )
    }
  }

  rootConfigurationSchema = (pluginManager: PluginManager) => {
    return {
      msa: ConfigurationSchema('MSA', {
        datasets: types.maybe(
          types.array(
            ConfigurationSchema('MSAEntry', {
              datasetId: {
                type: 'string',
                defaultValue: '',
              },
              description: {
                type: 'string',
                defaultValue: '',
              },
              name: {
                type: 'string',
                defaultValue: '',
              },
              adapter: pluginManager.pluggableConfigSchemaType('adapter'),
            }),
          ),
        ),
      }),
    }
  }
}
